<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, mutation } from '../api/client'
import RunPanel from './RunPanel.vue'
import LearningEvidenceCard from './LearningEvidenceCard.vue'
import type {LearningEvidence} from '../types/practice'
type Criterion={criterion_version_id:string;dimension:string;scenario:string;expected_behavior:string;pass_rule:string;critical:boolean;allowed_methods:string[];required_artifact_types:string[];limitations:string[]}
type Command={id:string;argv:string[];status:string;exit_code?:number;matches_current_code?:boolean}
type Snapshot={files:Record<string,string>;files_hash:string;commands:{id:string;argv:string[];exit_code:number;stdout:string;stderr:string;matches_submitted_code:boolean}[]}
type Submission={submission_id:string;version_no:number;code_version:string;summary:string;attachment_ids:string[];explanation_answers:{question:string;answer:string;criterion_version_ids:string[]}[];transfer_notes:string[];workspace_snapshot:Snapshot}
type Plan={plan_id:string;plan_version_id:string;version:number;version_no:number;kind:string}
type Delivery={learning_evidence:LearningEvidence;practice_id:string;exercise:string;workspace_revision:number;criteria:Criterion[];commands:Command[];task:{task_id:string;version:number;status:string;current_submission_id:string}|null;submissions:{submission_id:string;version_no:number;current:boolean}[];submission:Submission|null;assessment:{assessment_id:string;version:number;reviews:StoredReview[];confirmation:{confirmation_id:string;decision:string;revoked:boolean;revocation_reason:string|null}[];items:{criterion_version_id:string;verdict:string;rationale:string;limitations:string[]}[]}|null;assessment_run_id:string|null;plans:Plan[]}
type StoredReview={review_id:string;decision:'accept'|'request_revision';criterion_decisions:{criterion_version_id:string;verdict:'pass'|'fail'|'unknown';method:string;reason:string;self_review_record?:Record<string,string>|null}[]}
type Decision={id:string;verdict:'pass'|'fail'|'unknown';method:string;reason:string;procedure:string;observed:string;environment:string}
const props=defineProps<{workspaceId:string;practiceId:string}>()
const emit=defineEmits<{changed:[];plan:[plan:Plan]}>()
const write=mutation(),data=ref<Delivery|null>(null),busy=ref(false),selectedSubmission=ref(''),summary=ref(''),transfer=ref(''),minutes=ref<number|null>(null),commandIds=ref<string[]>([]),answers=ref<Record<string,string>>({}),decisions=ref<Decision[]>([]),decision=ref<'accept'|'request_revision'>('request_revision'),acknowledged=ref(false),planAcknowledged=ref(false),planReason=ref(''),planId=ref(''),savedPlan=ref<Plan|null>(null),file=ref('')
const externalHelp=ref('unknown'),hintCount=ref(0),assistanceNote=ref('')
let reviewKey='',loadedCommands=false
const base=computed(()=>'/studio/workspaces/'+props.workspaceId+'/practices/'+props.practiceId)
const current=computed(()=>!!data.value?.submission&&data.value.submission.submission_id===data.value.task?.current_submission_id)
const explanations=computed(()=>data.value?.criteria.filter(c=>c.required_artifact_types.includes('explanation_answer'))??[])
const mayReview=computed(()=>current.value&&data.value?.task?.status==='submitted'&&!!data.value.assessment)
const reviewReady=computed(()=>mayReview.value&&acknowledged.value&&decisions.value.length===data.value?.criteria.length&&decisions.value.every(d=>d.reason.trim()&&d.method&&(d.verdict!=='pass'||d.method!=='human_review'||(d.procedure.trim()&&d.observed.trim()&&d.environment.trim()))))
function initialize(value:Delivery){
  data.value=value
  if(!selectedSubmission.value&&value.submission)selectedSubmission.value=value.submission.submission_id
  if(!loadedCommands){commandIds.value=value.commands.filter(c=>c.status==='completed').map(c=>c.id);loadedCommands=true}
  if(value.submission&&!Object.keys(value.submission.workspace_snapshot.files).includes(file.value))file.value=Object.keys(value.submission.workspace_snapshot.files).sort()[0]??''
  const key=value.assessment?value.assessment.assessment_id+':'+value.assessment.version:''
  if(key!==reviewKey){
    reviewKey=key;acknowledged.value=false
    const previous=value.assessment?.reviews.at(-1)
    decision.value=previous?.decision??'request_revision'
    decisions.value=value.criteria.map(c=>{
      const stored=previous?.criterion_decisions.find(d=>d.criterion_version_id===c.criterion_version_id)
      return {id:c.criterion_version_id,verdict:stored?.verdict??'unknown',method:stored?.method??(c.allowed_methods.includes('human_review')?'human_review':c.allowed_methods.includes('user_reported')?'user_reported':''),reason:stored?.reason??'',procedure:stored?.self_review_record?.procedure??'',observed:stored?.self_review_record?.observed??'',environment:stored?.self_review_record?.environment??''}
    })
  }
  if(!value.plans.some(p=>p.plan_id===planId.value))planId.value=value.plans[0]?.plan_id??''
}
async function load(){try{initialize(await api<Delivery>(base.value+'/delivery'+(selectedSubmission.value?'?submission_id='+selectedSubmission.value:'')))}catch(e){ElMessage.error(String(e))}}
async function submit(){if(!data.value)return;busy.value=true;try{const value=await write<Delivery>(base.value+'/submissions','POST',{expected_revision:data.value.workspace_revision,summary:summary.value.trim(),command_ids:commandIds.value,explanation_answers:explanations.value.filter(c=>answers.value[c.criterion_version_id]?.trim()).map(c=>({question:c.scenario,answer:answers.value[c.criterion_version_id]!.trim(),criterion_version_ids:[c.criterion_version_id]})),transfer_notes:transfer.value.split('\n').map(s=>s.trim()).filter(Boolean),actual_minutes:minutes.value,external_help:externalHelp.value,reported_hint_count:hintCount.value,assistance_note:assistanceNote.value});selectedSubmission.value=value.submission!.submission_id;initialize(value);emit('changed');ElMessage.success('代码与记录已冻结，条件仍待逐项人工核对。')}catch(e){ElMessage.error(String(e))}finally{busy.value=false}}
async function review(){const v=data.value;if(!v?.assessment||!v.submission||!v.task)return;busy.value=true;try{initialize(await write<Delivery>(base.value+'/assessments/'+v.assessment.assessment_id+'/confirm','POST',{expected_version:v.assessment.version,expected_task_version:v.task.version,decision:decision.value,criterion_decisions:decisions.value.map(d=>({criterion_version_id:d.id,verdict:d.verdict,method:d.method,evidence_refs:v.submission!.attachment_ids,reason:d.reason,self_review_record:d.method==='human_review'?{procedure:d.procedure,observed:d.observed,environment:d.environment,code_version:v.submission!.code_version}:null})),supplementary_evidence_ids:[],scope_acknowledged:acknowledged.value}));emit('changed');ElMessage.success(decision.value==='accept'?'人工验收已记录，可单独更新已有计划。':'已记录返修意见，可重新提交成果。')}catch(e){ElMessage.error(String(e))}finally{busy.value=false}}
async function revoke(){const v=data.value;if(!v?.assessment||!v.task)return;try{const {value}=await ElMessageBox.prompt('说明撤销原因；关联计划中的验收记录将变为待复核。','撤销本次验收',{inputValidator:s=>!!s.trim()||'请填写原因'});busy.value=true;initialize(await write<Delivery>(base.value+'/assessments/'+v.assessment.assessment_id+'/revoke','POST',{expected_version:v.assessment.version,expected_task_version:v.task.version,reason:value}));emit('changed');ElMessage.success('已撤销；需要新提交后重新验收。')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e))}finally{busy.value=false}}
async function updatePlan(){const p=data.value?.plans.find(p=>p.plan_id===planId.value);if(!p)return;busy.value=true;try{savedPlan.value=await write<Plan>(base.value+'/plan-updates','POST',{plan_id:p.plan_id,base_plan_version_id:p.plan_version_id,expected_plan_version:p.version,reason:planReason.value,scope_acknowledged:planAcknowledged.value});planAcknowledged.value=false;emit('plan',savedPlan.value);await load();ElMessage.success(savedPlan.value.kind==='study'?'成果证据已写入模块计划新版本，原模块与旧版本保留。':'验收记录已写入已有计划的新草稿；核对后可在计划页采纳。')}catch(e){ElMessage.error(String(e))}finally{busy.value=false}}
onMounted(load)
</script>
<template>
<section v-if="data" class="delivery">
  <h2>练习成果、人工验收与计划更新</h2><LearningEvidenceCard :evidence="data.learning_evidence"/><p>{{data.exercise}}</p><el-alert title="提交会冻结代码与材料；材料盘点不调用模型或执行代码。退出码不代替本人解释，完整条件由你逐项核对。" type="info" :closable="false"/>
  <el-collapse><el-collapse-item title="1 · 提交当前工作区成果" name="submit"><el-alert v-if="data.task?.status==='accepted'" title="此任务已验收；需要修改成果时，先撤销当前验收，再提交新版本。" type="warning" :closable="false"/><el-form label-position="top"><el-form-item label="本次成果说明"><el-input v-model="summary" type="textarea" :rows="3" maxlength="8000"/></el-form-item><el-form-item label="附带已有运行记录（不会重新执行）"><el-checkbox-group v-model="commandIds"><div v-for="c in data.commands" :key="c.id"><el-checkbox :value="c.id" :disabled="c.status!=='completed'">{{JSON.stringify(c.argv)}} · {{c.status==='completed'?'退出码 '+c.exit_code:'尚未完成'}} · {{c.matches_current_code?'绑定当前代码':'旧记录或与当前代码不符，仅存档'}}</el-checkbox></div></el-checkbox-group></el-form-item><el-form-item v-for="c in explanations" :key="c.criterion_version_id" :label="'本人解释：'+c.scenario"><p class="muted">{{c.expected_behavior}}</p><el-input v-model="answers[c.criterion_version_id]" type="textarea" :rows="3" maxlength="12000" placeholder="请写自己的理解；留空会保持材料不足，不能整体接受。"/></el-form-item><el-form-item label="迁移记录（每行一项，可留空）"><el-input v-model="transfer" type="textarea"/></el-form-item><template v-if="data.learning_evidence.assistance"><el-form-item label="本次外部帮助（本人声明）"><el-select v-model="externalHelp"><el-option label="未明确" value="unknown"/><el-option label="未使用外部帮助" value="none"/><el-option label="使用过其他助手、提示或代写" value="used"/></el-select></el-form-item><el-form-item label="本人申报收到的提示次数"><el-input-number v-model="hintCount" :min="0" :max="10000"/></el-form-item><el-form-item label="帮助情况补充说明"><el-input v-model="assistanceNote" type="textarea" maxlength="2000"/></el-form-item></template><el-form-item label="本人实际投入分钟（可留空）"><el-input-number v-model="minutes" :min="0" :max="100000"/></el-form-item><el-button type="primary" :loading="busy" :disabled="!summary.trim()||data.task?.status==='accepted'" @click="submit">冻结并提交新版本</el-button></el-form></el-collapse-item></el-collapse>
  <template v-if="data.submission"><h3>2 · 核对提交快照</h3><el-select v-model="selectedSubmission" @change="load"><el-option v-for="s in data.submissions" :key="s.submission_id" :value="s.submission_id" :label="'提交 v'+s.version_no+(s.current?' · 当前':' · 历史只读')"/></el-select><p>{{data.submission.summary}}</p><p class="version">{{data.submission.code_version}}</p><el-select v-model="file" placeholder="冻结文件"><el-option v-for="path in Object.keys(data.submission.workspace_snapshot.files).sort()" :key="path" :value="path" :label="path"/></el-select><pre class="code">{{data.submission.workspace_snapshot.files[file]}}</pre><details v-for="c in data.submission.workspace_snapshot.commands" :key="c.id"><summary>{{JSON.stringify(c.argv)}} · 退出码 {{c.exit_code}} · {{c.matches_submitted_code?'已绑定提交代码':'未证明对应此代码版本，仅历史存档'}}</summary><pre>{{c.stdout}}{{c.stderr}}</pre></details><h4>冻结的本人解释与迁移记录</h4><p v-for="a in data.submission.explanation_answers" :key="a.question">{{a.question}}：{{a.answer}}</p><p v-if="!data.submission.explanation_answers.length" class="muted">未提供本人解释。</p><p v-for="t in data.submission.transfer_notes" :key="t">{{t}}</p>
  <RunPanel v-if="data.assessment_run_id&&!data.assessment" :run-id="data.assessment_run_id" @changed="load"/>
  <template v-if="data.assessment"><h3>3 · 完整条件人工验收</h3><el-alert v-for="confirmation in data.assessment.confirmation" :key="confirmation.confirmation_id" :title="(confirmation.decision==='accept'?'已记录接受':'已记录返修')+(confirmation.revoked?' · 已撤销：'+confirmation.revocation_reason:'')" :type="confirmation.revoked?'warning':confirmation.decision==='accept'?'success':'info'" :closable="false"/><el-alert v-if="!current" title="这是历史提交，不能用旧审阅验收当前成果。" type="warning" :closable="false"/><article v-for="(c,i) in data.criteria" :key="c.criterion_version_id" class="criterion"><h4>{{i+1}}. {{c.dimension}} · {{c.scenario}} {{c.critical?'（关键）':''}}</h4><p>预期：{{c.expected_behavior}}</p><p>通过规则：{{c.pass_rule}}</p><p class="muted">必需材料：{{c.required_artifact_types.join('、')}}</p><p v-for="note in data.assessment.items.find(a=>a.criterion_version_id===c.criterion_version_id)?.limitations" :key="note" class="muted">{{note}}</p><template v-if="decisions[i]"><el-select v-model="decisions[i]!.verdict" :disabled="!mayReview"><el-option label="未知 / 尚无充分证据" value="unknown"/><el-option label="通过" value="pass"/><el-option label="不通过" value="fail"/></el-select><el-select v-model="decisions[i]!.method" :disabled="!mayReview"><el-option v-for="method in c.allowed_methods.filter(m=>m!=='model_review')" :key="method" :value="method" :label="method==='human_review'?'本人逐项自验':'本人报告'"/></el-select><el-input v-model="decisions[i]!.reason" :disabled="!mayReview" type="textarea" placeholder="分项结论理由（必填）"/><template v-if="decisions[i]!.method==='human_review'"><el-input v-model="decisions[i]!.procedure" :disabled="!mayReview" placeholder="实际核对步骤"/><el-input v-model="decisions[i]!.observed" :disabled="!mayReview" placeholder="实际观察结果（不能只写已通过）"/><el-input v-model="decisions[i]!.environment" :disabled="!mayReview" placeholder="核对环境与范围"/><small class="version">自验版本固定为 {{data.submission.code_version}}</small></template></template></article><el-radio-group v-model="decision" :disabled="!mayReview"><el-radio value="request_revision">要求返修 / 补充材料</el-radio><el-radio value="accept">接受本次完整条件范围</el-radio></el-radio-group><p><el-checkbox v-model="acknowledged" :disabled="!mayReview">我已核对完整条件、材料和此次范围；这是本人自验，不是自动能力认证。</el-checkbox></p><el-button type="primary" :loading="busy" :disabled="!reviewReady" @click="review">保存人工验收决定</el-button><el-button v-if="current&&data.task?.status==='accepted'" type="warning" :disabled="busy" @click="revoke">撤销当前验收</el-button></template>
  <h3>4 · 更新已有学习计划</h3><p v-if="data.task?.status!=='accepted'" class="muted">先完成当前提交的人工验收。</p><p v-else-if="!data.plans.length" class="muted">当前目标不在最新计划中，请先处理计划与目标版本。</p><template v-else><el-select v-model="planId"><el-option v-for="p in data.plans" :key="p.plan_id" :value="p.plan_id" :label="'已有计划 v'+p.version_no+' · '+(p.kind==='study'?'模块计划':p.kind==='draft'?'草稿':'已采纳')"/></el-select><el-input v-model="planReason" type="textarea" maxlength="4000" placeholder="记录此次验收如何影响已有计划（不会删除目标或改写旧版本）"/><p><el-checkbox v-model="planAcknowledged">我确认将本次验收记录写入已有计划的新版本，保留原模块和历史；传统计划草稿仍须另行采纳。</el-checkbox></p><el-button type="primary" :loading="busy" :disabled="!current||!planAcknowledged||!planReason.trim()" @click="updatePlan">写入已有计划的新版本</el-button></template><router-link v-if="savedPlan" :to="savedPlan.kind==='study'?{path:'/studio',query:{...$route.query,study_plan:savedPlan.plan_id}}:{path:'/planning',query:{plan:savedPlan.plan_id}}">查看计划新版本 {{savedPlan.version_no??savedPlan.version}} →</router-link>
  </template><el-empty v-else description="尚未提交成果。展开上方表单，填写成果说明和自己的解释。"/>
</section>
</template>
<style scoped>
.delivery{padding:4px 12px;line-height:1.8}.delivery .el-select{width:100%;margin:8px 0}.delivery .el-input{margin:6px 0}.delivery .el-form-item{display:block}.delivery .el-checkbox{height:auto;white-space:normal;align-items:flex-start;margin:8px 0}.muted{font-size:12px;color:#718078}.version{display:block;overflow-wrap:anywhere;font:12px/1.8 Consolas,monospace}.code{background:#172723;color:#e0ebe3;padding:16px;max-height:320px;overflow:auto;white-space:pre;font:12px/1.7 Consolas,monospace}.criterion{border-top:1px solid #dce5df;padding:12px 0;margin:12px 0}details pre{white-space:pre-wrap;max-height:240px;overflow:auto;background:#f4f7f4;padding:12px}summary{cursor:pointer}h3{margin-top:28px}a{display:block;margin:16px 0}
</style>
